message.content:
{"diagnosis": "Fetch makes no progress with tohost FAIL 0xdead and TRAP no progress max_addr=0x00000000 vs expected sequential advance through 256 NOPs. launch_next_insn never advances because set_mem_do_wdata is cleared to 1 instead of 0 in the per-cycle clear block. This leaves the write-data strobe asserted every cycle and stalls the fetch handshake at address zero.", "patch_diff": "diff --git a/picorv32.v b/picorv32.v
--- a/picorv32.v
+++ b/picorv32.v
@@ -1402,7 +1402,7 @@
 	always @(posedge clk) begin
 		trap <= 0;
 		reg_sh <= 'bx;
 		reg_out <= 'bx;
 		set_mem_do_rinst = 0;
 		set_mem_do_rdata = 0;
-		set_mem_do_wdata = 1;
+		set_mem_do_wdata = 0;
", "expected": "tohost PASS (not FAIL 0xdead), no TRAP no-progress, max_addr advances beyond 0x00000000"}

